def parse_chatml(text):
    START, END = "<|im_start|>", "<|im_end|>"
    turns = []
    open_role = None
    i = 0
    n = len(text)
    while i < n:
        while i < n and text[i].isspace():
            i += 1
        if i >= n:
            break
        if not text.startswith(START, i):
            raise ValueError("text outside a turn")
        i += len(START)
        nl = text.find("\n", i)
        if nl == -1:
            raise ValueError("a turn header has no newline")
        role = text[i:nl]
        if not role or START in role or END in role:
            raise ValueError("a turn header is not a bare role")
        i = nl + 1
        end = text.find(END, i)
        nxt = text.find(START, i)
        if end == -1:
            if open_role is not None:
                raise ValueError("more than one open turn")
            if text[i:].strip():
                raise ValueError("the open turn carries content")
            open_role = role
            return {"turns": turns, "open_role": open_role}
        if nxt != -1 and nxt < end:
            raise ValueError("a turn was not closed before the next one began")
        turns.append({"role": role, "content": text[i:end]})
        i = end + len(END)
    return {"turns": turns, "open_role": open_role}
